import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

@DisplayName("80/74_populating_next_right_pointers_in_each_node_ii (incomplete)")
class SolutionIncompleteTest {

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldConnectNextPointersOnSparseTree() {

        Solution solution = new Solution();

        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(4);
        root.left.right = new Node(5);
        root.right.right = new Node(7);

        solution.connect(root);

        assertEquals(Arrays.asList(1, 2, 3, 4, 5, 7), collectLevelOrderWithNext(root));
        assertNull(root.next);
        assertEquals(3, root.left.next.val);
        assertNull(root.right.next);
        assertEquals(5, root.left.left.next.val);
        assertEquals(7, root.left.right.next.val);
        assertNull(root.right.right.next);
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldHandleEmptyTree() {

        Solution solution = new Solution();

        assertNull(solution.connect(null));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldHandleSingleNode() {

        Solution solution = new Solution();

        Node root = new Node(1);

        solution.connect(root);

        assertNull(root.next);
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldConnectLeftOnlyChildrenAcrossParents() {

        Solution solution = new Solution();

        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(4);
        root.right.left = new Node(5);

        solution.connect(root);

        assertEquals(5, root.left.left.next.val);
        assertNull(root.right.left.next);
    }

    private List<Integer> collectLevelOrderWithNext(Node root) {

        List<Integer> values = new ArrayList<>();
        Node levelStart = root;

        while (levelStart != null) {
            Node current = levelStart;
            Node nextLevel = null;

            while (current != null) {
                values.add(current.val);

                if (nextLevel == null) {
                    if (current.left != null) {
                        nextLevel = current.left;
                    } else if (current.right != null) {
                        nextLevel = current.right;
                    }
                }

                current = current.next;
            }

            levelStart = nextLevel;
        }

        return values;
    }
}

